SELECT c.owner_id AS ownerId, COALESCE(SUM(COALESCE(c.sign_amount, 0)), 0) AS actualValue FROM crm_contract c WHERE c.owner_id IN
#{oid}
AND COALESCE(c.contract_status, '') NOT IN ('Draft', 'Terminated') AND COALESCE(c.sign_time, c.create_time)::date >= #{startDate}::date AND COALESCE(c.sign_time, c.create_time)::date <= #{endDate}::date GROUP BY c.owner_id

SELECT c.owner_id AS ownerId, COUNT(*)::numeric AS actualValue FROM crm_contract c WHERE c.owner_id IN
#{oid}
AND COALESCE(c.contract_status, '') NOT IN ('Draft', 'Terminated') AND ( c.sign_time IS NOT NULL OR c.contract_status IN ('Active', 'Expired') ) AND COALESCE(c.sign_time, c.create_time)::date >= #{startDate}::date AND COALESCE(c.sign_time, c.create_time)::date <= #{endDate}::date GROUP BY c.owner_id

SELECT o.user_id::text AS ownerId, o.stage AS stage, o.close_reason AS closeReason, COALESCE(o.close_date, o.update_time) AS closeAt FROM crm_opty o WHERE o.user_id IS NOT NULL AND o.user_id::text IN
#{oid}
AND COALESCE(o.close_date, o.update_time)::date >= #{startDate}::date AND COALESCE(o.close_date, o.update_time)::date <= #{endDate}::date AND ( o.close_date IS NOT NULL OR o.stage ILIKE '%closed%' OR o.stage ILIKE '%won%' OR o.stage ILIKE '%lost%' OR o.stage IN ('赢单', '成交', '输单') OR o.close_reason IS NOT NULL )

SELECT a.user_id::text AS ownerId, COUNT(DISTINCT contact_key)::numeric AS actualValue FROM ( SELECT a.user_id, CASE WHEN LOWER(COALESCE(a.subject_type, '')) IN ('contact', '客户', '联系人') THEN a.subject_id WHEN LOWER(COALESCE(a.relate_type, '')) IN ('contact', '客户', '联系人', '业务联系人') THEN a.relate_id ELSE NULL END AS contact_key, COALESCE(a.started_date, a.create_time) AS evt_at FROM crm_activity a WHERE a.user_id IS NOT NULL AND a.user_id::text IN
#{oid}
AND a.event_type IN
#{et}
) a WHERE a.contact_key IS NOT NULL AND a.contact_key <> '' AND a.evt_at::date >= #{startDate}::date AND a.evt_at::date <= #{endDate}::date GROUP BY a.user_id

SELECT a.user_id::text AS ownerId, COUNT(DISTINCT contact_key)::numeric AS actualValue FROM ( SELECT a.user_id, CASE WHEN LOWER(COALESCE(a.subject_type, '')) IN ('contact', '客户', '联系人') THEN a.subject_id WHEN LOWER(COALESCE(a.relate_type, '')) IN ('contact', '客户', '联系人', '业务联系人') THEN a.relate_id ELSE NULL END AS contact_key, COALESCE(a.started_date, a.create_time) AS evt_at FROM crm_activity a WHERE a.user_id IS NOT NULL AND a.user_id::text IN
#{oid}
AND a.event_type IN
#{et}
AND a.event_type NOT IN
#{et}
AND COALESCE(a.status, '') NOT IN ('cancelled', 'canceled', 'noshow') ) a WHERE a.contact_key IS NOT NULL AND a.contact_key <> '' AND a.evt_at::date >= #{startDate}::date AND a.evt_at::date <= #{endDate}::date GROUP BY a.user_id

SELECT assignee AS ownerId, COUNT(DISTINCT lead_key)::numeric AS actualValue FROM ( SELECT COALESCE( NULLIF(a.payload->>'assigned_toid', ''), NULLIF(a.assigned_toid, ''), a.user_id::text ) AS assignee, COALESCE(NULLIF(a.subject_id, ''), a.relate_id) AS lead_key, COALESCE(a.started_date, a.create_time) AS evt_at FROM crm_activity a WHERE a.event_type = 'lead.assigned' AND COALESCE(a.channel, '') <> 'wecom_transfer' AND COALESCE(a.source, '') NOT IN ('wecom_transfer', 'transfer_customer') ) t WHERE t.assignee IS NOT NULL AND t.assignee <> '' AND t.assignee IN
#{oid}
AND t.lead_key IS NOT NULL AND t.lead_key <> '' AND t.evt_at::date >= #{startDate}::date AND t.evt_at::date <= #{endDate}::date GROUP BY t.assignee

SELECT a.user_id::text AS ownerId, COUNT(*)::numeric AS actualValue FROM crm_activity a WHERE a.user_id IS NOT NULL AND a.user_id::text IN
#{oid}
AND a.event_type IN
#{et}
AND COALESCE(a.started_date, a.create_time)::date >= #{startDate}::date AND COALESCE(a.started_date, a.create_time)::date <= #{endDate}::date GROUP BY a.user_id

SELECT o.user_id::text AS ownerId, COUNT(*)::numeric AS actualValue FROM crm_opty o WHERE o.user_id IS NOT NULL AND o.user_id::text IN
#{oid}
AND o.create_time::date >= #{startDate}::date AND o.create_time::date <= #{endDate}::date GROUP BY o.user_id

SELECT o.user_id::text AS ownerId, COALESCE(SUM(COALESCE(o.amount, 0)), 0) AS actualValue FROM crm_opty o WHERE o.user_id IS NOT NULL AND o.user_id::text IN
#{oid}
AND o.create_time::date >= #{startDate}::date AND o.create_time::date <= #{endDate}::date GROUP BY o.user_id
